package com.lendup.pagos.domain.model;
import static org.junit.jupiter.api.Assertions.*; import java.math.BigDecimal; import java.time.Instant; import java.util.UUID; import org.junit.jupiter.api.Test;
class GarantiaTest { private final Instant now=Instant.parse("2026-11-01T15:00:00Z");
  private Garantia constituida(String monto){var g=Garantia.nueva(UUID.randomUUID(),new BigDecimal(monto),"PEN",now);g.constituir(new BigDecimal(monto),now);return g;}
  @Test void nuevaQuedaPendienteSinSaldo(){var g=Garantia.nueva(UUID.randomUUID(),new BigDecimal("50"),"PEN",now);assertEquals(EstadoGarantia.PENDIENTE,g.estado());assertEquals(new BigDecimal("0.00"),g.saldoDisponible());assertFalse(g.constituida());}
  @Test void constituyeSoloPorElMontoAcordado(){var g=Garantia.nueva(UUID.randomUUID(),new BigDecimal("50"),"PEN",now);assertThrows(IllegalArgumentException.class,()->g.constituir(new BigDecimal("40"),now));g.constituir(new BigDecimal("50.00"),now);assertEquals(EstadoGarantia.CONSTITUIDA,g.estado());assertEquals(new BigDecimal("50.00"),g.saldoDisponible());assertThrows(IllegalStateException.class,()->g.constituir(new BigDecimal("50"),now));}
  @Test void devolucionTotalLaDejaDevuelta(){var g=constituida("50");g.registrarDevolucion(new BigDecimal("50"),now);assertEquals(EstadoGarantia.DEVUELTA,g.estado());assertEquals(new BigDecimal("50.00"),g.montoDevuelto());assertNotNull(g.cerradaEn());}
  @Test void afectacionParcialYDevolucionDelSaldo(){var g=constituida("50");g.aplicarAfectacion(new BigDecimal("20"),now);assertEquals(EstadoGarantia.AFECTADA_PARCIALMENTE,g.estado());assertEquals(new BigDecimal("30.00"),g.saldoDisponible());g.registrarDevolucion(new BigDecimal("30"),now);assertEquals(EstadoGarantia.AFECTADA_PARCIALMENTE,g.estado());assertEquals(new BigDecimal("0.00"),g.saldoDisponible());}
  @Test void afectacionTotalCierraLaGarantia(){var g=constituida("50");g.aplicarAfectacion(new BigDecimal("50"),now);assertEquals(EstadoGarantia.AFECTADA_TOTALMENTE,g.estado());assertNotNull(g.cerradaEn());}
  @Test void nuncaDevuelveOAfectaMasQueElSaldo(){var g=constituida("50");g.aplicarAfectacion(new BigDecimal("20"),now);assertThrows(IllegalArgumentException.class,()->g.registrarDevolucion(new BigDecimal("31"),now));assertThrows(IllegalArgumentException.class,()->g.aplicarAfectacion(new BigDecimal("31"),now));}
  @Test void soloUnaPendientePuedeCancelarseYNoSeDevuelveSinConstituir(){var g=Garantia.nueva(UUID.randomUUID(),new BigDecimal("50"),"PEN",now);assertThrows(IllegalStateException.class,()->g.registrarDevolucion(BigDecimal.ONE,now));g.cancelar(now);assertEquals(EstadoGarantia.CANCELADA,g.estado());assertThrows(IllegalStateException.class,()->g.cancelar(now));}
}
